//! The date predicates of TPC-H Q1, Q3-Q7, Q10, Q12, Q14, Q15 and Q20 on the
//! kernels, against Spark 4.2 (`tests/fixtures/spark-4.2.0/tpch-date-predicates.json`,
//! generated by `tests/scripts/gen_tpch_date_goldens.py`): each comparison of
//! the WHERE clauses at probe dates around its bound, the bounds themselves
//! (`DATE '1998-12-01' - INTERVAL '90' DAY`, `+ INTERVAL '3' MONTH`) and
//! `extract(year FROM ...)`, in both ANSI modes and every operand shape.
#![forbid(unsafe_code)]

use std::collections::{BTreeMap, BTreeSet};

use krishiv_testkit::fn_matrix::{Expected, Field, MatrixCase, Mode};
use krishiv_testkit::kernel_eval::{CellOutcome, run_cell};
use serde_json::{Value, json};

type R = Result<(), Box<dyn std::error::Error>>;

#[test]
fn tpch_date_predicates_match_spark() -> R {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/tpch-date-predicates.json");
    let fixture: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    let mut queries = BTreeSet::new();
    let mut failures = Vec::new();
    for (n, case) in fixture["cases"]
        .as_array()
        .ok_or("cases")?
        .iter()
        .enumerate()
    {
        let sql = case["sql"].as_str().ok_or("sql")?;
        let ty = case["type"].as_str().ok_or("type")?;
        queries.insert(case["query"].as_str().ok_or("query")?);
        let cell = match ty {
            "date" => json!({"days": case["value"]}),
            _ => case["value"].clone(),
        };
        let function = match ty {
            "int" => "extract",
            "boolean" => "<",
            _ => "+",
        };
        for mode in Mode::ALL {
            let outcome = run_cell(&MatrixCase {
                id: format!("tpch#{n}/{}", mode.key()),
                base_id: format!("tpch#{n}"),
                function: function.to_owned(),
                family: "datetime".to_owned(),
                kind: "tpch".to_owned(),
                mode,
                sql: sql.to_owned(),
                conf: BTreeMap::new(),
                expected: Expected::Rows {
                    schema: vec![Field {
                        name: "c".to_owned(),
                        data_type: ty.to_owned(),
                        nullable: false,
                    }],
                    rows: vec![],
                    render: vec![],
                    ordered: false,
                    truncated: false,
                    typed_rows: Some(vec![vec![cell.clone()]]),
                    typed_unavailable: None,
                },
            });
            if outcome != CellOutcome::Pass {
                failures.push(format!("{sql} [{}]: {outcome:?}", mode.key()));
            }
        }
    }
    assert!(failures.is_empty(), "{failures:#?}");
    let expected: BTreeSet<&str> = [
        "Q1", "Q3", "Q4", "Q5", "Q6", "Q7", "Q10", "Q12", "Q14", "Q15", "Q20",
    ]
    .into_iter()
    .collect();
    assert_eq!(queries, expected);
    Ok(())
}
